def min_tile(g):
    h=len(g);w=len(g[0]);res=[]
    for hh in range(1,h+1):
        for ww in range(1,w+1):
            if h%hh==0 and w%ww==0 and all(g[r][c]==g[r%(hh)][c%(ww)] for r in range(h) for c in range(w)):
                res.append((hh,ww))
    return res
